#include <stdio.h>

int pair_exists(int a[], int n, int target) {
    int lo = 0, hi = n - 1;
    while (lo < hi) {
        long long s = (long long)a[lo] + a[hi];
        if (s == target) return 1;
        if (s < target) lo++;
        else hi--;
    }
    return 0;
}

