int count_pairs(int a[], int n, int target) {
    int lo = 0, hi = n - 1;
    int count = 0;
    while (lo < hi) {
        long long s = (long long)a[lo] + a[hi];
        if (s < target) {
            lo++;
        } else if (s > target) {
            hi--;
        } else {
            if (a[lo] == a[hi]) {
                int m = hi - lo + 1;
                count += m * (m - 1) / 2;
                break;
            }
            int cl = 1;
            while (a[lo + 1] == a[lo]) {
                cl++;
                lo++;
            }
            int cr = 1;
            while (a[hi - 1] == a[hi]) {
                cr++;
                hi--;
            }
            count += cl * cr;
            lo++;
            hi--;
        }
    }
    return count;
}

