int even_parity_count(int a[], int n) {
    int count = 0;
    for (int i = 0; i < n; i++) {
        int x = a[i];
        int bits = 0;
        while (x) {
            x &= x - 1;
            bits++;
        }
        if (bits % 2 == 0) count++;
