int pivot_index(int a[], int n) {
    long long total = 0;
    for (int i = 0; i < n; i++) total += a[i];
    long long left = 0;
    for (int i = 0; i < n; i++) {
        if (left == total - left - a[i]) return i;
        left += a[i];
    }
    return -1;
}

