int max_gain(int a[], int n) {
    int best = -1;
    int minSoFar = a[0];
    for (int i = 1; i < n; i++) {
        if (a[i] > minSoFar) {
            int gain = a[i] - minSoFar;
            if (gain > best) best = gain;
        }
        if (a[i] < minSoFar) minSoFar = a[i];
    }
    return best;
}

