int min_window_len(int a[], int n, int target) {
    long long sum = 0;
    int lo = 0;
    int best = 0;
    for (int hi = 0; hi < n; hi++) {
        sum += a[hi];
        while (sum >= target) {
            int len = hi - lo + 1;
            if (best == 0 || len < best) best = len;
            sum -= a[lo];
            lo++;
        }
    }
    return best;
}

