int max_water(int h[], int n) {
    int lo = 0, hi = n - 1;
    int best = 0;
    while (lo < hi) {
        int area = (hi - lo) * (h[lo] < h[hi] ? h[lo] : h[hi]);
        if (area > best) best = area;
        if (h[lo] < h[hi]) lo++;
        else hi--;
    }
    return best;
}

