long long max_subarray_sum(int a[], int n) {
    long long best = a[0];
    long long cur = a[0];
    for (int i = 1; i < n; i++) {
        if (cur + a[i] > a[i]) cur += a[i];
        else cur = a[i];
        if (cur > best) best = cur;
    }
    return best;
