int majority_element(int a[], int n) {
    int cand = 0;
    int count = 0;
    for (int i = 0; i < n; i++) {
        if (count == 0) cand = a[i];
        count += (a[i] == cand) ? 1 : -1;
    }
    count = 0;
    for (int i = 0; i < n; i++) {
        if (a[i] == cand) count++;
    }
    if (count > n / 2) return cand;
    return -1;
}

