void sort_flags(int a[], int n) {
    int lo = 0, mid = 0, hi = n - 1;
    while (mid <= hi) {
        if (a[mid] == 0) {
            int t = a[lo];
            a[lo] = a[mid];
            a[mid] = t;
            lo++;
            mid++;
        } else if (a[mid] == 1) {
            mid++;
        } else {
            int t = a[mid];
            a[mid] = a[hi];
            a[hi] = t;
            hi--;
        }
    }
}

